import { strict as assert } from 'node:assert';
import { createHash } from 'node:crypto';

const statuses = ['killed', 'survived', 'timeout', 'compileError', 'runtimeError'];
const metadataKeys = ['file', 'line', 'column', 'operator', 'original', 'replacement', 'description'];
const sha256 = value => createHash('sha256').update(value).digest('hex');

export function reconcileMutationEvidence({ native, expected, files, expectedTests, sourceCalls = [] }) {
  assert.equal(native.schemaVersion, 1);
  assert.equal(native.packagePath, expected.packagePath);
  assert.deepEqual(native.ignored, expected.ignored);
  const expectedById = new Map(expected.mutants.map(row => [row.id, row]));
  const byId = new Map(native.mutants.map(row => [row.id, row]));
  assert.equal(byId.size, native.mutants.length, 'Duplicate native identity');
  assert.deepEqual([...byId.keys()].toSorted(), [...expectedById.keys()].toSorted(), 'Selected identity set changed');
  const totals = Object.fromEntries(statuses.map(status => [status, 0]));
  totals.ignored = native.ignored.length;
  for (const row of native.mutants) {
    assert(statuses.includes(row.status), 'Unknown native status');
    for (const key of metadataKeys) assert.deepEqual(row[key], expectedById.get(row.id)[key], 'Native metadata changed: ' + row.id + '/' + key);
    totals[row.status]++;
  }
  assert.deepEqual(totals, native.totals, 'Native totals do not match individual identities');
  const manifests = new Map();
  const reports = new Map();
  for (const row of files) {
    assert.equal(row.bytes.length, row.expectedBytes);
    assert.equal(sha256(row.bytes), row.expectedSha256);
    const document = JSON.parse(row.bytes.toString());
    assert.equal(document.schemaVersion, 1);
    if (row.path.startsWith('mutation-manifest-')) {
      assert.equal(document.packagePath, native.packagePath);
      assert.deepEqual(document.tests, expectedTests, 'Selected full-suite test paths changed');
      assert.equal(document.timeoutFloorMs, 5000);
      assert.equal(document.timeoutFactor, 3);
      for (const mutant of document.mutants) {
        assert(byId.has(mutant.id), 'Manifest contains an unknown identity: ' + mutant.id);
        for (const key of metadataKeys) assert.deepEqual(mutant[key], byId.get(mutant.id)[key], 'Manifest metadata changed: ' + mutant.id + '/' + key);
      }
      manifests.set(row.path, document);
    } else {
      assert(row.path.startsWith('mutation-report-'), 'Unknown shard evidence path');
      reports.set(row.path, document);
    }
  }
  assert.equal(manifests.size, native.shardCount, 'Native shard count differs from emitted manifests');
  const assignments = new Map(native.mutants.map(row => [row.id, []]));
  for (const [path, document] of manifests) for (const mutant of document.mutants) assignments.get(mutant.id).push(path);
  assert([...assignments.values()].every(rows => rows.length > 0), 'Selected identity was never assigned');
  const runs = sourceCalls.filter(row => row.event === 'source-podman-call' && row.command === 'run');
  const returnsByPid = new Map();
  for (const row of sourceCalls) if (row.event === 'source-podman-returned' && row.command === 'run') {
    const records = returnsByPid.get(row.pid) ?? [];
    records.push(row);
    returnsByPid.set(row.pid, records);
  }
  const pairs = [];
  const pairedManifests = new Set();
  const pairedReports = new Set();
  for (const run of runs) {
    const volumes = run.args.flatMap((value, index) => value === '--volume' ? [run.args[index + 1]] : []);
    const manifestVolume = volumes.filter(value => value.endsWith(':/manifest:ro'));
    const reportVolume = volumes.filter(value => value.endsWith(':/out:rw'));
    assert.equal(manifestVolume.length, 1);
    assert.equal(reportVolume.length, 1);
    const manifestDirectory = manifestVolume[0].slice(0, -':/manifest:ro'.length).split('/').at(-1);
    const reportDirectory = reportVolume[0].slice(0, -':/out:rw'.length).split('/').at(-1);
    assert(/^mutation-manifest-[A-Za-z0-9]+$/.test(manifestDirectory));
    assert(/^mutation-report-[A-Za-z0-9]+$/.test(reportDirectory));
    const manifestPath = manifestDirectory + '/shard-manifest.json';
    const reportPath = reportDirectory + '/shard-report.json';
    assert(manifests.has(manifestPath), 'Source invocation lacks its manifest');
    assert(!pairedManifests.has(manifestPath), 'Manifest was invoked more than once without separate evidence');
    pairedManifests.add(manifestPath);
    const manifest = manifests.get(manifestPath);
    const report = reports.get(reportPath);
    const sourceReturns = (returnsByPid.get(run.pid) ?? []).filter(row => Date.parse(row.observedAt) >= Date.parse(run.observedAt));
    const sourceReturn = sourceReturns.length === 1 ? sourceReturns[0] : undefined;
    if (report) {
      assert.equal(report.shardId, manifest.shardId);
      assert(!pairedReports.has(reportPath));
      pairedReports.add(reportPath);
      const ids = manifest.mutants.map(row => row.id);
      assert.deepEqual(report.results.map(row => row.id), ids.slice(0, report.results.length));
      assert.deepEqual(report.unrun, ids.slice(report.results.length));
      for (const [index, result] of report.results.entries()) {
        assert.equal(result.position, index + 1);
        assert(statuses.includes(result.status));
      }
    }
    pairs.push({ manifestPath, reportPath, sourceCall: run, sourceReturn, sourceReturnMatches: sourceReturns.length, reportPresent: !!report, baseline: report?.baseline, results: report?.results, unrun: report?.unrun, anomaly: report?.anomaly });
  }
  const resultsByIdentity = new Map(native.mutants.map(row => [row.id, []]));
  for (const pair of pairs) for (const result of pair.results ?? []) resultsByIdentity.get(result.id).push({ manifestPath: pair.manifestPath, reportPath: pair.reportPath, baselineGreen: pair.baseline.green, ...result });
  const perIdentity = native.mutants.map(row => {
    const emittedResults = resultsByIdentity.get(row.id);
    return { ...row, assignedManifests: assignments.get(row.id), emittedResults, finalStatusBackedByGreenBaselineReport: emittedResults.some(result => result.baselineGreen && result.status === row.status && result.position === row.position) };
  });
  const sourceMutationCompleted = totals.runtimeError === 0 && perIdentity.every(row => row.finalStatusBackedByGreenBaselineReport);
  return {
    selectedIdentities: byId.size,
    manifestAttempts: manifests.size,
    reportAttempts: reports.size,
    sourceRunCalls: runs.length,
    assignments: [...assignments.values()].reduce((sum, rows) => sum + rows.length, 0),
    totals,
    sourceMutationCompleted,
    nativeRunInfrastructureClean: native.infraErrors.length === 0 && totals.runtimeError === 0,
    allAttemptReportsRetained: pairs.length === manifests.size && pairedReports.size === reports.size && pairs.every(row => row.reportPresent),
    allSourceRunReturnsRetained: pairs.length === manifests.size && pairs.every(row => row.sourceReturnMatches === 1),
    sourceReportedTestRunnerTerminals: native.mutants.filter(row => ['killed', 'survived', 'timeout'].includes(row.status)).length,
    assertionExecutionIsNotInferredFromStatus: true,
    compilationTerminalIdentities: totals.compileError,
    infrastructureIdentities: totals.runtimeError,
    sourceInfraErrors: native.infraErrors.length,
    unrunAssignments: pairs.reduce((sum, row) => sum + (row.unrun?.length ?? 0), 0),
    physicalAttemptMappingAvailable: runs.length === manifests.size,
    pairs,
    perIdentity,
  };
}

