import { strict as assert } from 'node:assert';
import { readFileSync, writeFileSync } from 'node:fs';
import { gunzipSync } from 'node:zlib';
import { createHash } from 'node:crypto';
import { join } from 'node:path';
import { homedir } from 'node:os';
import { reconcileMutationEvidence } from './verify-toml-mutation-evidence.ts';

const read = path => JSON.parse(readFileSync(path, 'utf8'));
const main = join(homedir(), 'Monochromatic');
const old = JSON.parse(gunzipSync(readFileSync(join(main, 'doc/audit/depot-toml-mutation-native-2026-10-17.evidence.json.gz'))));
const audit = read(join(main, 'doc/audit/depot-toml-reconciliation-2026-10-17.evidence.json'));
const tests = audit.continuation.development.terminal.reconciliation.selectedTestFiles;

function load({ runId, attemptId }) {
  const root = 'collected-' + runId;
  const index = read(join(root, 'artifact-index.native-accounting.json'));
  const artifact = index.artifacts.find(row => !attemptId || row.attempt_id === attemptId);
  const directory = join(root, artifact.extraction);
  const bounded = read(join(directory, 'toml-bounded-package.module.toml-edit.test.mutation-results.json'));
  return { bounded, directory, files: bounded.shardEvidence.map(row => ({ path: row.path, expectedBytes: row.bytes, expectedSha256: row.sha256, bytes: readFileSync(join(directory, 'toml-mutation-shards', row.path)) })) };
}

function rejection({ name, action }) {
  let diagnostic;
  try { action(); }
  catch (error) { diagnostic = String(error); }
  assert(diagnostic, 'Negative evidence fixture was accepted: ' + name);
  return { name, diagnostic };
}

const pilot = load({ runId: 'vlrxjltfkq' });
const pilotNative = read(join(pilot.directory, pilot.bounded.nativeReports[0].artifactPath));
const pilotExpected = { ...old, mutants: old.mutants.filter(row => row.id === '9cd1056a095eaea1') };
const pilotInput = { native: pilotNative, expected: pilotExpected, files: pilot.files, expectedTests: tests, sourceCalls: pilot.bounded.sourcePodmanCalls };
const pilotResult = reconcileMutationEvidence(pilotInput);
assert.equal(pilotResult.sourceMutationCompleted, true);
assert.equal(pilotResult.compilationTerminalIdentities, 1);
assert.equal(pilotResult.assertionTerminalIdentities, 0);
assert.equal(pilotResult.physicalAttemptMappingAvailable, true);
const legacy = load({ runId: 'p6vm5s00w6', attemptId: 'q3xbl70q20' });
const legacyResult = reconcileMutationEvidence({ native: old, expected: old, files: legacy.files, expectedTests: tests });
assert.equal(legacyResult.selectedIdentities, 3062);
assert.equal(legacyResult.manifestAttempts, 9037);
assert.equal(legacyResult.assignments, 18338);
assert.equal(legacyResult.sourceMutationCompleted, false);
assert.equal(legacyResult.infrastructureIdentities, 3062);
assert.equal(legacyResult.assertionTerminalIdentities, 0);
const wrongNative = structuredClone(pilotNative);
wrongNative.mutants[0].id = '0000000000000000';
const duplicateNative = structuredClone(pilotNative);
duplicateNative.mutants.push(duplicateNative.mutants[0]);
const changedManifest = { ...pilot.files[0] };
const contents = JSON.parse(changedManifest.bytes.toString());
contents.mutants[0].id = '0000000000000000';
changedManifest.bytes = Buffer.from(JSON.stringify(contents));
changedManifest.expectedBytes = changedManifest.bytes.length;
changedManifest.expectedSha256 = createHash('sha256').update(changedManifest.bytes).digest('hex');
const negatives = [
  rejection({ name: 'wrong native identity', action: () => reconcileMutationEvidence({ ...pilotInput, native: wrongNative }) }),
  rejection({ name: 'duplicate native identity', action: () => reconcileMutationEvidence({ ...pilotInput, native: duplicateNative }) }),
  rejection({ name: 'unknown manifest identity with matching byte receipt', action: () => reconcileMutationEvidence({ ...pilotInput, files: [changedManifest, ...pilot.files.slice(1)] }) }),
  rejection({ name: 'censored selected test file', action: () => reconcileMutationEvidence({ ...pilotInput, expectedTests: tests.slice(1) }) }),
];
const report = { observedAt: new Date().toISOString(), realPilot: { selected: pilotResult.selectedIdentities, compilerTerminals: pilotResult.compilationTerminalIdentities, assertionTerminals: pilotResult.assertionTerminalIdentities, completeSelectedPilot: pilotResult.sourceMutationCompleted, physicalMapping: pilotResult.physicalAttemptMappingAvailable }, realHistoricalFailure: { selected: legacyResult.selectedIdentities, attempts: legacyResult.manifestAttempts, assignments: legacyResult.assignments, infra: legacyResult.infrastructureIdentities, sourceCompleted: legacyResult.sourceMutationCompleted }, negatives, verifierSha256: createHash('sha256').update(readFileSync('verify-toml-mutation-evidence.ts')).digest('hex') };
writeFileSync('toml-mutation-evidence-controls.json', JSON.stringify(report, null, 2) + '\n');
console.log(JSON.stringify(report));

sourceSchema.text:
/**
 Final run report: native JSON schema plus terminal findings.

 No mutation score anywhere by design; the report carries raw totals,
 per-mutant records with provenance, and infra errors.

 @example
 ```ts
 const report = buildRunReport({ outcome, packagePath: 'package/module/fs-path' });
 ```
 */

import type {
  IgnoredMutant,
} from '../engine/enumerate.ts';
import type { MutantStatus, } from '../engine/types.ts';
import type { RunOutcome, } from './orchestrate.ts';

/**
 Current run-report schema version.
 */
export const RUN_REPORT_SCHEMA_VERSION = 1;

/**
 Raw totals per final status plus suppressions.
 */
export type RunTotals = {
  readonly killed: number;
  readonly survived: number;
  readonly timeout: number;
  readonly compileError: number;
  readonly runtimeError: number;
  readonly ignored: number;
};

/**
 One mutant record in the final report.
 */
export type RunMutantRecord = {
  readonly id: string;
  readonly file: string;
  readonly line: number;
  readonly column: number;
  readonly operator: string;
  readonly original: string;
  readonly replacement: string;
  readonly description: string;
  readonly status: MutantStatus;
  readonly position: number;
  readonly rerunCount: number;
  readonly confirmed: boolean;
};

/**
 Complete native run report.
 */
export type RunReport = {
  readonly schemaVersion: typeof RUN_REPORT_SCHEMA_VERSION;
  readonly packagePath: string;
  readonly totals: RunTotals;
  readonly mutants: readonly RunMutantRecord[];
  readonly ignored: readonly IgnoredMutant[];
  readonly infraErrors: readonly string[];
  readonly shardCount: number;
};

/**
 Builds the native JSON run report from an orchestration outcome.

 @param options - Outcome and package identity.

 @returns Serialisable run report.

 @example
 ```ts
 const report = buildRunReport({ outcome, packagePath });
 ```
 */
export function buildRunReport(options: {
  readonly outcome: RunOutcome;
  readonly packagePath: string;
},): RunReport {
  /**
   Totals accumulated across final results.
   */
  const totals = options.outcome
    .results
    .reduce(
      function addResult(
        accumulated,
        result,
      ): RunTotals {
        return {
          killed: accumulated.killed + (result.status === 'killed' ? 1 : 0),
          survived: accumulated.survived + (result.status === 'survived' ? 1 : 0),
          timeout: accumulated.timeout + (result.status === 'timeout' ? 1 : 0),
          compileError: accumulated.compileError
            + (result.status === 'compileError' ? 1 : 0),
          runtimeError: accumulated.runtimeError
            + (result.status === 'runtimeError' ? 1 : 0),
          ignored: accumulated.ignored,
        };
      },
      {
        killed: 0,
        survived: 0,
        timeout: 0,
        compileError: 0,
        runtimeError: 0,
        ignored: options.outcome
          .ignored
          .length,
      },
    );

  return {
    schemaVersion: RUN_REPORT_SCHEMA_VERSION,
    packagePath: options.packagePath,
    totals,
    mutants: options.outcome
      .results
      .map(function toRecord(result,): RunMutantRecord {
        return {
          id: result.mutant
            .id,
          file: result.mutant
            .file,
          line: result.mutant
            .line,
          column: result.mutant
            .column,
          operator: result.mutant
            .operator,
          original: result.mutant
            .original,
          replacement: result.mutant
            .replacement,
          description: result.mutant
            .description,
          status: result.status,
          position: result.position,
          rerunCount: result.rerunCount,
          confirmed: result.confirmed,
        };
      },),
    ignored: options.outcome
      .ignored,
    infraErrors: options.outcome
      .infraErrors,
    shardCount: options.outcome
      .shardCount,
  };
}

/**
 Formats terminal output: totals plus survivor and timeout findings.

 @param report - Completed run report.

 @returns Human-readable multi-line summary.

 @example
 ```ts
 console.log(formatTerminalSummary(report));
 ```
 */
export function formatTerminalSummary(report: RunReport,): string {
  /**
   Actionable findings: survivors and timeouts.
   */
  const findings = report.mutants
    .filter(function actionable(record,): boolean {
      return (record.status === 'survived') || (record.status === 'timeout');
    },)
    .map(function toLine(record,): string {
      return `${record.status === 'survived' ? 'Survived' : 'Timeout'}: ${record.file}:${
        String(record.line,)
      }:${String(record.column,)} ${record.operator} ${record.description}${
        record.confirmed ? '' : ' (unconfirmed)'
      }`;
    },);
  /**
   Infra error lines, when any.
   */
  const infra = report.infraErrors
    .map(function toLine(message,): string {
      return `Infra: ${message}`;
    },);

  return [
    ...findings,
    ...infra,
    `Killed: ${String(report.totals
      .killed,)}`,
    `Survived: ${String(report.totals
      .survived,)}`,
    `Timeout: ${String(report.totals
      .timeout,)}`,
    `CompileError: ${String(report.totals
      .compileError,)}`,
    `RuntimeError: ${String(report.totals
      .runtimeError,)}`,
    `Ignored: ${String(report.totals
      .ignored,)}`,
    `Shards: ${String(report.shardCount,)}`,
  ]
    .join('\n',);
}

/**
 Shard manifest and report schema shared by host and container.

 The host writes one manifest per shard (mounted read-only); the
 container writes one report to the report mount. Versioned so future
 shape changes fail loudly instead of misparsing.

 @example
 ```ts
 const manifest: ShardManifest = {
   schemaVersion: 1,
   shardId: 'src__a.ts-0',
   packagePath: 'package/module/fs-path',
   mutants: [],
   tests: ['src/a.unit.test.ts'],
   timeoutFloorMs: 5000,
   timeoutFactor: 3,
 };
 ```
 */

import type {
  Mutant,
  MutantStatus,
} from './engine/types.ts';

/**
 Current schema version stamped into manifests and reports.
 */
export const SHARD_SCHEMA_VERSION = 1;

/**
 One shard's worth of work, written by the host.
 */
export type ShardManifest = {
  schemaVersion: typeof SHARD_SCHEMA_VERSION;
  shardId: string;
  packagePath: string;
  mutants: readonly Mutant[];
  tests: readonly string[];
  timeoutFloorMs: number;
  timeoutFactor: number;
};

/**
 Outcome of one mutant execution inside a shard container.

 `position` is one-based; position 1 ran in an untainted container, so
 confirmation runs check it.
 */
export type ShardMutantResult = {
  readonly id: string;
  readonly status: MutantStatus;
  readonly position: number;
  readonly durationMs: number;
  readonly detail: string;
};

/**
 Baseline measurements taken before any mutant runs.
 */
export type ShardBaseline = {
  readonly green: boolean;
  readonly testsMs: number;
  readonly tsgoMs: number;
  readonly detail: string;
};

/**
 One shard's results, written by the container to the report mount.

 `unrun` lists mutant ids abandoned after the first anomaly; the host
 reshards them into fresh containers.
 */
export type ShardReport = {
  schemaVersion: typeof SHARD_SCHEMA_VERSION;
  shardId: string;
  baseline: ShardBaseline;
  results: readonly ShardMutantResult[];
  unrun: readonly string[];
  anomaly: string;
};

/**
 Shared engine type declarations: mutation operators, candidate
 replacements, and fully-identified mutants.

 @example
 ```ts
 const status: MutantStatus = 'killed';
 ```
 */

/**
 Mutation operator family names, mirroring the Stryker mutator families
 whose replacement tables serve as the parity spec.
 */
export type OperatorName =
  | 'arithmetic'
  | 'equality'
  | 'logical'
  | 'conditional'
  | 'boolean'
  | 'string'
  | 'unary'
  | 'update'
  | 'array'
  | 'object'
  | 'optional-chaining'
  | 'block'
  | 'method'
  | 'arrow'
  | 'regex';

/**
 Final classification of one executed (or filtered) mutant.

 `compileError` comes from the per-mutant tsgo check; `runtimeError`
 marks infrastructure failures, never test-detected kills.
 */
export type MutantStatus =
  | 'killed'
  | 'survived'
  | 'timeout'
  | 'compileError'
  | 'runtimeError';

/**
 Candidate replacement produced by one operator for one AST node,
 before identity assignment.

 Offsets are UTF-16 string indices as returned by yuku-parser's JS
 bindings (probe-verified on astral characters), so
 `source.slice(start, end)` is exact.
 */
export type Replacement = {
  readonly start: number;
  readonly end: number;
  readonly text: string;
  readonly operator: OperatorName;
  readonly description: string;
};

/**
 Fully-identified mutant ready for manifest serialisation.
 */
export type Mutant = {
  readonly id: string;
  readonly file: string;
  readonly start: number;
  readonly end: number;
  readonly line: number;
  readonly column: number;
  readonly operator: OperatorName;
  readonly original: string;
  readonly replacement: string;
  readonly description: string;
};

/**
 Minimal structural view of an ESTree node used by operators; operators
 narrow via `type` plus property checks so their code stays independent
 of the parser's full node union.
 */
export type EstreeNode = {
  readonly type: string;
  readonly start: number;
  readonly end: number;
  readonly [key: string]: unknown;
};

runnerContractSource.text:
/**
 Test execution with process-group timeout kill.

 @example
 ```ts
 await runTests({ cwd: '/work/packages/module/fs-path', tests: ['src/a.unit.test.ts'], timeoutMs: 5000 });
 ```
 */

import { spawn as nodeSpawn, } from 'node:child_process';
import { once, } from 'node:events';

import { tagged, } from '@monochromatic-dev/module-logger/ts';

/**
 Module logger for container-side test execution.
 */
const l = tagged({ tag: 'mutation-test-container', },);

/**
 Outcome of one full selected-test run.
 */
export type TestRunOutcome = {
  readonly kind: 'passed' | 'failed' | 'timeout';
  readonly durationMs: number;
  readonly detail: string;
};

/**
 Runs one test file under plain node in its own process group.

 The child leads a process group (detached) so a timeout kill also
 reaps any grandchildren a mutant may have spawned; a mutant is
 arbitrary bad code and must not outlive its verdict.

 @param options - Working directory, test file, and timeout.

 @returns Exit outcome for this file.

 @example
 ```ts
 await runOneTest({ cwd, test: 'src/a.unit.test.ts', timeoutMs: 5000 });
 ```
 */
async function runOneTest(options: {
  readonly cwd: string;
  readonly test: string;
  readonly timeoutMs: number;
},): Promise<TestRunOutcome> {
  /**
   Logger scoped to this test invocation.
   */
  const rl = tagged({
    tag: runOneTest.name,
    l,
  },);
  /**
   Start timestamp for duration measurement.
   */
  const startedAt = performance.now();
  /**
   Mutable timeout marker shared with the kill timer.
   */
  const state = { timedOut: false, };
  /**
   Detached child so it leads its own killable process group.
   */
  const child = nodeSpawn(
    'node',
    [options.test,],
    {
      cwd: options.cwd,
      detached: true,
      // Inherit so baseline failures land in the container log; mutant
      // runs are noisy but the old tool streamed runner output too.
      stdio: 'inherit',
    },
  );
  /**
   Timeout handle killing the whole process group.
   */
  const timer = setTimeout(
    function killGroup(): void {
      state.timedOut = true;
      rl.warn(`timeout after ${String(options.timeoutMs,)}ms: ${options.test}`,);

      if ((typeof child.pid) === 'number') {
        try {
          process.kill(
            -child.pid,
            'SIGKILL',
          );
        }
        catch (error) {
          rl.warn(`process group kill failed: ${String(error,)}`,);
        }
      }
    },
    options.timeoutMs,
  );
  /**
   Scope guard clearing the kill timer on every exit path.
   */
  using stopTimer = {
    [Symbol.dispose](): void {
      clearTimeout(timer,);
    },
  };

  try {
    /**
     Exit event payload (code, signal) from the child process; `once`
     rejects when the child emits `error` (spawn failure). Kept as
     unknowns since only equality checks and stringification follow.
     */
    const exitInfo: readonly unknown[] = await once(
      child,
      'exit',
    );
    /**
     Exit code, number or null per child_process semantics.
     */
    const [
      code,
      signal,
    ] = exitInfo;

    if (state.timedOut)
      return {
        kind: 'timeout',
        durationMs: performance.now() - startedAt,
        detail: `timeout running ${options.test}`,
      };

    if (code === 0)
      return {
        kind: 'passed',
        durationMs: performance.now() - startedAt,
        detail: '',
      };

    return {
      kind: 'failed',
      durationMs: performance.now() - startedAt,
      detail: `${options.test} exited with ${JSON.stringify(code ?? signal
        ?? 'unknown',)}`,
    };
  }
  catch (error) {
    rl.error(`spawn failed for ${options.test}: ${String(error,)}`,);
    return {
      kind: 'failed',
      durationMs: performance.now() - startedAt,
      detail: `spawn error: ${String(error,)}`,
    };
  }
}

/**
 Runs selected tests in order, stopping at the first failure.

 First failure wins because a failing test already proves the mutant
 detected; remaining tests add wall time without information.

 @param options - Working directory, test files, and per-run timeout.

 @returns Aggregate outcome across the executed prefix of tests.

 @example
 ```ts
 await runTests({ cwd, tests: ['src/a.unit.test.ts'], timeoutMs: 5000 });
 ```
 */
export async function runTests(options: {
  readonly cwd: string;
  readonly tests: readonly string[];
  readonly timeoutMs: number;
},): Promise<TestRunOutcome> {
  /**
   Aggregate start timestamp across all files.
   */
  const startedAt = performance.now();

  /* oxlint-disable no-await-in-loop */
  for (const test of options.tests) {
    /**
     Outcome for this test file; sequential by design, since running
     later files after a failure adds wall time without information.
     */
    const outcome = await runOneTest({
      cwd: options.cwd,
      test,
      timeoutMs: options.timeoutMs,
    },);

    if (outcome.kind !== 'passed')
      return {
        kind: outcome.kind,
        durationMs: performance.now() - startedAt,
        detail: outcome.detail,
      };
  }
  /* oxlint-enable no-await-in-loop */

  return {
    kind: 'passed',
    durationMs: performance.now() - startedAt,
    detail: '',
  };
}

/**
 Sequential per-mutant execution loop inside one shard container.

 Applies each mutant by string-offset splice, type-checks, runs the
 selected tests, restores the original file, and classifies the result.
 The first anomaly (timeout, spawn failure, restore failure) aborts the
 remainder: the container is tainted and the host reshards what's left.

 @example
 ```ts
 await runMutantLoop({ packageCwd, manifest, baselineTestsMs: 900 });
 ```
 */

import {
  readFile,
  writeFile,
} from 'node:fs/promises';
import { join, } from 'node:path';

import { tagged, } from '@monochromatic-dev/module-logger/ts';

import { spliceReplacement, } from '../engine/splice.ts';
import { runBuildStep, } from './build-step.ts';
import { runTests, } from './test-run.ts';
import { tsgoCheck, } from './tsgo-check.ts';
import type { MutantStatus, } from '../engine/types.ts';
import type {
  ShardManifest,
  ShardMutantResult,
} from '../shard-schema.ts';

/**
 Module logger for the container-side mutant loop.
 */
const l = tagged({ tag: 'mutation-test-container', },);

/**
 Loop output: per-mutant results plus the taint-abandoned remainder.
 */
export type MutantLoopOutput = {
  readonly results: readonly ShardMutantResult[];
  readonly unrun: readonly string[];
  readonly anomaly: string;
};

/**
 Statuses that taint the container for every later mutant.

 A timeout means a mutant's process tree had to be killed; a runtime
 error means infrastructure misbehaved. Either way later results in
 this container are untrustworthy.
 */
const TAINTING_STATUSES: ReadonlySet<MutantStatus> = new Set([
  'timeout',
  'runtimeError',
],);

/**
 Computes the effective per-mutant test timeout.

 @param options - Manifest limits and measured baseline duration.

 @returns Milliseconds allowed for one mutant's test run.

 @example
 ```ts
 effectiveTimeoutMs({ floorMs: 5000, factor: 3, baselineMs: 900 });
 // 5000
 ```
 */
export function effectiveTimeoutMs(options: {
  readonly floorMs: number;
  readonly factor: number;
  readonly baselineMs: number;
},): number {
  return Math.max(
    options.floorMs,
    Math.ceil(options.factor * options.baselineMs,),
  );
}

/**
 Runs every mutant in the shard sequentially.

 @param options - Package cwd, shard manifest, and baseline test time.

 @returns Results, unrun remainder, and anomaly description.

 @example
 ```ts
 const output = await runMutantLoop({ packageCwd, manifest, baselineTestsMs: 900 });
 ```
 */
export async function runMutantLoop(options: {
  readonly packageCwd: string;
  readonly manifest: Readonly<ShardManifest>;
  readonly baselineTestsMs: number;
},): Promise<MutantLoopOutput> {
  /**
   Logger scoped to this shard's loop.
   */
  const rl = tagged({
    tag: runMutantLoop.name,
    l,
  },);
  /**
   Effective test timeout for every mutant in this shard.
   */
  const timeoutMs = effectiveTimeoutMs({
    floorMs: options.manifest
      .timeoutFloorMs,
