import { strict as assert } from 'node:assert';
import { appendFileSync, chmodSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
import { setTimeout as wait } from 'node:timers/promises';
import { runTests } from '/baked/package/cli/mutation-test/src/container/test-run.ts';
import { tsgoCheck } from '/baked/package/cli/mutation-test/src/container/tsgo-check.ts';
import { runMutantLoop } from '/baked/package/cli/mutation-test/src/container/mutant-loop.ts';

const startedAt = new Date().toISOString();
const cgroup = () => Object.fromEntries(['memory.max', 'memory.events', 'cpu.max', 'pids.max', 'pids.events'].map(name => [name, readFileSync('/sys/fs/cgroup/' + name, 'utf8').trim()]));
const cgroupBefore = cgroup();
assert.equal(cgroupBefore['memory.max'], '2147483648');
assert.equal(cgroupBefore['pids.max'], '512');
const cpu = cgroupBefore['cpu.max'].split(/\s+/).map(Number);
assert.equal(cpu[0] / cpu[1], 2);
const root = '/work/spawn-fixture';
const bin = '/work/control-bin';
const output = '/out/spawn-control.json';
mkdirSync(root, { recursive: true });
mkdirSync(bin);
const originalPath = process.env.PATH;
const source = 'export const value: number = 1;\n';
writeFileSync(join(root, 'subject.ts'), source);
writeFileSync(join(root, 'tsconfig.json'), JSON.stringify({ compilerOptions: { target: 'ESNext', module: 'NodeNext', strict: true, types: [], noEmit: true }, include: ['subject.ts'] }));
writeFileSync(join(root, 'package.json'), JSON.stringify({ type: 'module' }));
writeFileSync(join(root, 'subject.unit.test.mjs'), "import {value} from './subject.ts'; import{strict as assert}from'node:assert'; import{appendFileSync}from'node:fs'; appendFileSync('/work/test-invocations.jsonl', JSON.stringify({token:process.env.CONTROL_TOKEN,value})+'\\n'); assert.equal(value,1);\n");
const sourceModules = ['container/test-run.ts', 'container/mutant-loop.ts', 'container/tsgo-check.ts', 'container/build-step.ts', 'engine/splice.ts'].map(relative => {
  const path = '/baked/package/cli/mutation-test/src/' + relative;
  const bytes = readFileSync(path);
  return { relative, bytes: bytes.length, sha256: createHash('sha256').update(bytes).digest('hex') };
});
const compilerVersion = JSON.parse(readFileSync('/baked/node_modules/typescript/package.json', 'utf8')).version;
const launcher = join(bin, 'node');
const shim = '#!' + process.execPath + '\n' + `import{spawnSync}from'node:child_process';import{appendFileSync,existsSync,unlinkSync}from'node:fs';const args=process.argv.slice(2);const result=spawnSync(${JSON.stringify(process.execPath)},args,{stdio:'inherit',env:process.env});const row={event:'real-node-forward-return',args,status:result.status,signal:result.signal,error:result.error?{name:result.error.name,message:result.error.message,code:result.error.code}:undefined};appendFileSync('/work/node-forwards.jsonl',JSON.stringify(row)+'\\n');if(args[0]==='/baked/node_modules/typescript/lib/tsc.js'&&result.status===0&&existsSync('/work/remove-node-after-compiler')){unlinkSync(${JSON.stringify(launcher)});appendFileSync('/work/node-forwards.jsonl',JSON.stringify({event:'disposable-node-launcher-removed-after-real-compiler',status:result.status})+'\\n');}process.exit(result.status??1);\n`;
writeFileSync(launcher, shim);
chmodSync(launcher, 0o755);
process.env.PATH = bin;
const baselineType = await tsgoCheck({ cwd: root });
assert.equal(baselineType.clean, true);
process.env.CONTROL_TOKEN = 'baseline';
const baselineTests = await runTests({ cwd: root, tests: ['subject.unit.test.mjs'], timeoutMs: 5000 });
assert.equal(baselineTests.kind, 'passed');
const start = source.indexOf('1');
const manifest = {
  schemaVersion: 1,
  shardId: 'disposable-source-spawn-control',
  packagePath: 'spawn-fixture',
  timeoutFloorMs: 5000,
  timeoutFactor: 3,
  tests: ['subject.unit.test.mjs'],
  mutants: [{ id: 'c000000000000001', file: 'subject.ts', line: 1, column: start + 1, start, end: start + 1, operator: 'disposable-numeric-control', original: '1', replacement: '2', description: 'Fixture changes 1 to 2' }],
};
process.env.CONTROL_TOKEN = 'genuine-kill';
const positive = await runMutantLoop({ packageCwd: root, manifest, baselineTestsMs: baselineTests.durationMs });
assert.equal(positive.results[0].status, 'killed');
assert.equal(readFileSync(join(root, 'subject.ts'), 'utf8'), source);
const invocationsBeforeFault = readFileSync('/work/test-invocations.jsonl', 'utf8').trim().split('\n').map(JSON.parse);
assert(invocationsBeforeFault.some(row => row.token === 'genuine-kill' && row.value === 2));
writeFileSync('/work/remove-node-after-compiler', 'fault only in disposable launcher\n');
process.env.CONTROL_TOKEN = 'spawn-failure';
const fault = await runMutantLoop({ packageCwd: root, manifest, baselineTestsMs: baselineTests.durationMs });
assert.equal(fault.results[0].status, 'killed');
assert.equal(fault.anomaly, '');
assert.deepEqual(fault.unrun, []);
assert.equal(existsSync(launcher), false);
assert.equal(readFileSync(join(root, 'subject.ts'), 'utf8'), source);
const invocationsAfterFault = readFileSync('/work/test-invocations.jsonl', 'utf8').trim().split('\n').map(JSON.parse);
assert.deepEqual(invocationsAfterFault, invocationsBeforeFault, 'Fault test must never have launched');
const forwards = readFileSync('/work/node-forwards.jsonl', 'utf8').trim().split('\n').map(JSON.parse);
assert(forwards.some(row => row.event === 'disposable-node-launcher-removed-after-real-compiler' && row.status === 0));
assert(forwards.filter(row => row.args?.[0] === '/baked/node_modules/typescript/lib/tsc.js').every(row => row.status === 0));
process.env.PATH = originalPath;
const marker = '/work/ordered-test-markers';
writeFileSync(join(root, 'first.mjs'), "import{appendFileSync}from'node:fs';appendFileSync('/work/ordered-test-markers','first\\n');\n");
writeFileSync(join(root, 'second.mjs'), "import{appendFileSync}from'node:fs';appendFileSync('/work/ordered-test-markers','second\\n');\n");
const orderedPositive = await runTests({ cwd: root, tests: ['first.mjs', 'second.mjs'], timeoutMs: 5000 });
assert.equal(orderedPositive.kind, 'passed');
assert.equal(readFileSync(marker, 'utf8'), 'first\nsecond\n');
writeFileSync(marker, '');
appendFileSync(join(root, 'first.mjs'), "throw new Error('expected independent early-stop control');\n");
const earlyStop = await runTests({ cwd: root, tests: ['first.mjs', 'second.mjs'], timeoutMs: 5000 });
assert.equal(earlyStop.kind, 'failed');
assert.equal(readFileSync(marker, 'utf8'), 'first\n');
writeFileSync(join(root, 'slow.mjs'), 'setInterval(()=>{},1000);\n');
const timeout = await runTests({ cwd: root, tests: ['slow.mjs'], timeoutMs: 100 });
assert.equal(timeout.kind, 'timeout');
const result = { schemaVersion: 1, developmentOnly: true, startedAt, finishedAt: new Date().toISOString(), nodeVersion: process.version, nodeExecutable: process.execPath, compilerVersion, sourceModules, cgroupBefore, cgroupAfter: cgroup(), fixtureSource: source, fixtureManifest: manifest, baselineType, baselineTests, genuineAssertionKill: positive, missingNodeFalseKill: fault, testInvocations: invocationsAfterFault, realNodeForwards: forwards, earlyStop: { positive: orderedPositive, failedFirst: earlyStop, remainingTestUnexecuted: true }, timeout, sourceRestored: readFileSync(join(root, 'subject.ts'), 'utf8') === source, interpretation: 'The source returns killed even though the test child never started after the real compiler passed. This is a disposable fault control, not evidence that the separate cloud mutation campaign encountered a spawn failure.' };
writeFileSync(output, JSON.stringify(result, null, 2) + '\n');
await wait(200);
console.log(JSON.stringify({ event: 'actual-source-spawn-control-complete', falseKill: fault.results[0].status, testStartedForFault: false, sourceRestored: true }));

