/**
 Test execution with process-group timeout kill.

 @example
 ```ts
 await runTests({ cwd: '/work/packages/module/fs-path', tests: ['src/a.unit.test.ts'], timeoutMs: 5000 });
 ```
 */

import { spawn as nodeSpawn, } from 'node:child_process';
import { once, } from 'node:events';

import { tagged, } from '@monochromatic-dev/module-logger/ts';

/**
 Module logger for container-side test execution.
 */
const l = tagged({ tag: 'mutation-test-container', },);

/**
 Outcome of one full selected-test run.
 */
export type TestRunOutcome = {
  readonly kind: 'passed' | 'failed' | 'timeout';
  readonly durationMs: number;
  readonly detail: string;
};

/**
 Runs one test file under plain node in its own process group.

 The child leads a process group (detached) so a timeout kill also
 reaps any grandchildren a mutant may have spawned; a mutant is
 arbitrary bad code and must not outlive its verdict.

 @param options - Working directory, test file, and timeout.

 @returns Exit outcome for this file.

 @example
 ```ts
 await runOneTest({ cwd, test: 'src/a.unit.test.ts', timeoutMs: 5000 });
 ```
 */
async function runOneTest(options: {
  readonly cwd: string;
  readonly test: string;
  readonly timeoutMs: number;
},): Promise<TestRunOutcome> {
  /**
   Logger scoped to this test invocation.
   */
  const rl = tagged({
    tag: runOneTest.name,
    l,
  },);
  /**
   Start timestamp for duration measurement.
   */
  const startedAt = performance.now();
  /**
   Mutable timeout marker shared with the kill timer.
   */
  const state = { timedOut: false, };
  /**
   Detached child so it leads its own killable process group.
   */
  const child = nodeSpawn(
    'node',
    [options.test,],
    {
      cwd: options.cwd,
      detached: true,
      // Inherit so baseline failures land in the container log; mutant
      // runs are noisy but the old tool streamed runner output too.
      stdio: 'inherit',
    },
  );
  /**
   Timeout handle killing the whole process group.
   */
  const timer = setTimeout(
    function killGroup(): void {
      state.timedOut = true;
      rl.warn(`timeout after ${String(options.timeoutMs,)}ms: ${options.test}`,);

      if ((typeof child.pid) === 'number') {
        try {
          process.kill(
            -child.pid,
            'SIGKILL',
          );
        }
        catch (error) {
          rl.warn(`process group kill failed: ${String(error,)}`,);
        }
      }
    },
    options.timeoutMs,
  );
  /**
   Scope guard clearing the kill timer on every exit path.
   */
  using stopTimer = {
    [Symbol.dispose](): void {
      clearTimeout(timer,);
    },
  };

  try {
    /**
     Exit event payload (code, signal) from the child process; `once`
     rejects when the child emits `error` (spawn failure). Kept as
     unknowns since only equality checks and stringification follow.
     */
    const exitInfo: readonly unknown[] = await once(
      child,
      'exit',
    );
    /**
     Exit code, number or null per child_process semantics.
     */
    const [
      code,
      signal,
    ] = exitInfo;

    if (state.timedOut)
      return {
        kind: 'timeout',
        durationMs: performance.now() - startedAt,
        detail: `timeout running ${options.test}`,
      };

    if (code === 0)
      return {
        kind: 'passed',
        durationMs: performance.now() - startedAt,
        detail: '',
      };

    return {
      kind: 'failed',
      durationMs: performance.now() - startedAt,
      detail: `${options.test} exited with ${JSON.stringify(code ?? signal
        ?? 'unknown',)}`,
    };
  }
  catch (error) {
    rl.error(`spawn failed for ${options.test}: ${String(error,)}`,);
    return {
      kind: 'failed',
      durationMs: performance.now() - startedAt,
      detail: `spawn error: ${String(error,)}`,
    };
  }
}

/**
 Runs selected tests in order, stopping at the first failure.

 First failure wins because a failing test already proves the mutant
 detected; remaining tests add wall time without information.

 @param options - Working directory, test files, and per-run timeout.

 @returns Aggregate outcome across the executed prefix of tests.

 @example
 ```ts
 await runTests({ cwd, tests: ['src/a.unit.test.ts'], timeoutMs: 5000 });
 ```
 */
export async function runTests(options: {
  readonly cwd: string;
  readonly tests: readonly string[];
  readonly timeoutMs: number;
},): Promise<TestRunOutcome> {
  /**
   Aggregate start timestamp across all files.
   */
  const startedAt = performance.now();

  /* oxlint-disable no-await-in-loop */
  for (const test of options.tests) {
    /**
     Outcome for this test file; sequential by design, since running
     later files after a failure adds wall time without information.
     */
    const outcome = await runOneTest({
      cwd: options.cwd,
      test,
      timeoutMs: options.timeoutMs,
    },);

    if (outcome.kind !== 'passed')
      return {
        kind: outcome.kind,
        durationMs: performance.now() - startedAt,
        detail: outcome.detail,
      };
  }
  /* oxlint-enable no-await-in-loop */

  return {
    kind: 'passed',
    durationMs: performance.now() - startedAt,
    detail: '',
  };
}

/**
 Sequential per-mutant execution loop inside one shard container.

 Applies each mutant by string-offset splice, type-checks, runs the
 selected tests, restores the original file, and classifies the result.
 The first anomaly (timeout, spawn failure, restore failure) aborts the
 remainder: the container is tainted and the host reshards what's left.

 @example
 ```ts
 await runMutantLoop({ packageCwd, manifest, baselineTestsMs: 900 });
 ```
 */

import {
  readFile,
  writeFile,
} from 'node:fs/promises';
import { join, } from 'node:path';

import { tagged, } from '@monochromatic-dev/module-logger/ts';

import { spliceReplacement, } from '../engine/splice.ts';
import { runBuildStep, } from './build-step.ts';
import { runTests, } from './test-run.ts';
import { tsgoCheck, } from './tsgo-check.ts';
import type { MutantStatus, } from '../engine/types.ts';
import type {
  ShardManifest,
  ShardMutantResult,
} from '../shard-schema.ts';

/**
 Module logger for the container-side mutant loop.
 */
const l = tagged({ tag: 'mutation-test-container', },);

/**
 Loop output: per-mutant results plus the taint-abandoned remainder.
 */
export type MutantLoopOutput = {
  readonly results: readonly ShardMutantResult[];
  readonly unrun: readonly string[];
  readonly anomaly: string;
};

/**
 Statuses that taint the container for every later mutant.

 A timeout means a mutant's process tree had to be killed; a runtime
 error means infrastructure misbehaved. Either way later results in
 this container are untrustworthy.
 */
const TAINTING_STATUSES: ReadonlySet<MutantStatus> = new Set([
  'timeout',
  'runtimeError',
],);

/**
 Computes the effective per-mutant test timeout.

 @param options - Manifest limits and measured baseline duration.

 @returns Milliseconds allowed for one mutant's test run.

 @example
 ```ts
 effectiveTimeoutMs({ floorMs: 5000, factor: 3, baselineMs: 900 });
 // 5000
 ```
 */
export function effectiveTimeoutMs(options: {
  readonly floorMs: number;
  readonly factor: number;
  readonly baselineMs: number;
},): number {
  return Math.max(
    options.floorMs,
    Math.ceil(options.factor * options.baselineMs,),
  );
}

/**
 Runs every mutant in the shard sequentially.

 @param options - Package cwd, shard manifest, and baseline test time.

 @returns Results, unrun remainder, and anomaly description.

 @example
 ```ts
 const output = await runMutantLoop({ packageCwd, manifest, baselineTestsMs: 900 });
 ```
 */
export async function runMutantLoop(options: {
  readonly packageCwd: string;
  readonly manifest: Readonly<ShardManifest>;
  readonly baselineTestsMs: number;
},): Promise<MutantLoopOutput> {
  /**
   Logger scoped to this shard's loop.
   */
  const rl = tagged({
    tag: runMutantLoop.name,
    l,
  },);
  /**
   Effective test timeout for every mutant in this shard.
   */
  const timeoutMs = effectiveTimeoutMs({
    floorMs: options.manifest
      .timeoutFloorMs,
    factor: options.manifest
      .timeoutFactor,
    baselineMs: options.baselineTestsMs,
  },);
  /**
   Accumulated per-mutant results.
   */
  const results: ShardMutantResult[] = [];

  rl.info(
    `running ${String(options.manifest
      .mutants
      .length,)} mutants, timeout ${String(timeoutMs,)}ms`,
  );

  /* oxlint-disable no-await-in-loop */
  // Mutants share one work tree, so execution is sequential by design;
  // parallelism lives at the shard-container level on the host.
  for (const [
    index,
    mutant,
  ] of options.manifest
    .mutants
    .entries()) {
    /**
     Absolute path of the file under mutation in the work tree.
     */
    const filePath = join(
      options.packageCwd,
      mutant.file,
    );
    /**
     Pristine file text restored after the mutant's verdict.
     */
    const original = await readFile(
      filePath,
      'utf8',
    );
    /**
     Start timestamp for this mutant.
     */
    const startedAt = performance.now();
    /**
     Scope guard restoring pristine file text when this iteration
     exits, whatever the verdict; replaces try/finally per house style.
     */
    await using restoreOriginal = {
      async [Symbol.asyncDispose](): Promise<void> {
        await writeFile(
          filePath,
          original,
          'utf8',
        );
      },
    };

    try {
      await writeFile(
        filePath,
        spliceReplacement({
          source: original,
          start: mutant.start,
          end: mutant.end,
          text: mutant.replacement,
        },),
        'utf8',
      );

      /**
       Build verdict for the spliced mutant; tests exercise built
       output, so the build must precede them, and its declaration
       emit must precede the type gate.
       */
      const build = await runBuildStep({ packageCwd: options.packageCwd, },);
      /**
       Type-check verdict for the spliced mutant.
       */
      const typeCheck = build.clean
        ? await tsgoCheck({ cwd: options.packageCwd, },)
        : {
          clean: false,
          durationMs: 0,
          detail: build.detail,
        };
      /**
       Final status for this mutant.
       */
      const status: MutantStatus = await (async function classify(): Promise<MutantStatus> {
        if (!typeCheck.clean)
          return 'compileError';

        /**
         Test verdict for the compiling mutant.
         */
        const testRun = await runTests({
          cwd: options.packageCwd,
          tests: options.manifest
            .tests,
          timeoutMs,
        },);

        if (testRun.kind === 'passed')
          return 'survived';

        if (testRun.kind === 'timeout')
          return 'timeout';

        return 'killed';
      })();

      results.push({
        id: mutant.id,
        status,
        position: index + 1,
        durationMs: performance.now() - startedAt,
        detail: mutant.description,
      },);

      if (TAINTING_STATUSES.has(status,)) {
        rl.warn(`tainting status ${status} at position ${String(index + 1,)}; aborting remainder`,);
        // Expected taint, not an infrastructure failure: the result is
        // recorded and the unrun remainder reshards; anomaly stays empty
        // so the host does not flag the run as infra-failed.
        return {
          results,
          unrun: options.manifest
            .mutants
            .slice(index + 1,)
            .map(function toId(remaining,): string {
              return remaining.id;
            },),
          anomaly: '',
        };
      }
    }
    catch (error) {
      rl.error(`infrastructure failure at position ${String(index + 1,)}: ${String(error,)}`,);
      results.push({
        id: mutant.id,
        status: 'runtimeError',
        position: index + 1,
        durationMs: performance.now() - startedAt,
        detail: String(error,),
      },);
      return {
        results,
        unrun: options.manifest
          .mutants
          .slice(index + 1,)
          .map(function toId(remaining,): string {
            return remaining.id;
          },),
        anomaly: `infrastructure failure on mutant ${mutant.id}: ${String(error,)}`,
      };
    }
  }
  /* oxlint-enable no-await-in-loop */

  return {
    results,
    unrun: [],
    anomaly: '',
  };
}

/**
 Per-mutant TypeScript check via the native tsgo binary.

 Chosen over a watch daemon on measured evidence: tsgo 7.0.1-rc watch
 output has no completion terminator, while a warm one-shot `--noEmit`
 check measured 0.125 s on the module-test package. Incrementality
 comes from each package tsconfig's own build-info settings, warmed by
 the baseline check; a CLI `--incremental` flag would conflict with
 project-file configuration.

 @example
 ```ts
 await tsgoCheck({ cwd: '/work/packages/module/fs-path' });
 ```
 */

import spawn from 'nano-spawn';

import { tagged, } from '@monochromatic-dev/module-logger/ts';

import { isRecord, } from '../is-record.ts';

/**
 Cap on captured diagnostic text per failure, keeping shard reports
 readable when tsc emits hundreds of errors.
 */
const DIAGNOSTIC_TEXT_LIMIT = 4_000;

/**
 Module logger for container-side type checking.
 */
const l = tagged({ tag: 'mutation-test-container', },);

/**
 Outcome of one tsgo project check.
 */
export type TsgoOutcome = {
  readonly clean: boolean;
  readonly durationMs: number;
  readonly detail: string;
};

/**
 Extracts compiler diagnostics from a spawn failure.

 nano-spawn attaches captured stdout/stderr to its error; without them
 a red-baseline report only says "exit code 1", which is undebuggable.

 @param error - Caught spawn error.

 @returns Combined diagnostic text, possibly empty.

 @example
 ```ts
 diagnosticsFromError(caught);
 ```
 */
export function diagnosticsFromError(error: unknown,): string {
  if (!isRecord(error,))
    return '';

  return [
    error.stdout,
    error.stderr,
  ]
    .filter(function isText(value,): value is string {
      return ((typeof value) === 'string') && (value !== '');
    },)
    .join('\n',)
    .slice(
      0,
      DIAGNOSTIC_TEXT_LIMIT,
    );
}

/**
 Runs one incremental project check in the package directory.

 Uses the repo-root tsc bin (tsgo under typescript 7) resolved through
 the baked workspace instead of a package-local dependency.

 @param options - Package working directory inside the work tree.

 @returns Check outcome; `clean` false means the mutant cannot compile.

 @example
 ```ts
 const outcome = await tsgoCheck({ cwd: packageCwd });
 ```
 */
export async function tsgoCheck(options: {
  readonly cwd: string;
},): Promise<TsgoOutcome> {
  /**
   Logger scoped to this check invocation.
   */
  const rl = tagged({
    tag: tsgoCheck.name,
    l,
  },);
  /**
   Start timestamp for duration measurement.
   */
  const startedAt = performance.now();

  try {
    await spawn(
      'node',
      [
        '/baked/node_modules/typescript/lib/tsc.js',
        '--noEmit',
        '--project',
        '.',
      ],
      { cwd: options.cwd, },
    );
    return {
      clean: true,
      durationMs: performance.now() - startedAt,
      detail: '',
    };
  }
  catch (error) {
    rl.debug(`type check rejected mutant: ${String(error,)}`,);
    return {
      clean: false,
      durationMs: performance.now() - startedAt,
      detail: `${String(error,)} ${diagnosticsFromError(error,)}`.trim(),
    };
  }
}

/**
 In-container package build via rolldown, once per mutant.

 Tests exercise built output (repo convention), so every mutant must be
 built before tests can observe it; the build also emits declaration
 files (oxc isolatedDeclarations), which the tsgo gate needs for
 package self-reference imports. Packages without rolldown configs (like
 the fixture) skip the step: their tests import source directly.

 @example
 ```ts
 await runBuildStep({ packageCwd: '/work/packages/module/fs-path' });
 ```
 */

import { readdir, } from 'node:fs/promises';
import { join, } from 'node:path';

import spawn from 'nano-spawn';

import { tagged, } from '@monochromatic-dev/module-logger/ts';

import { diagnosticsFromError, } from './tsgo-check.ts';
import { WORK_MOUNT, } from '../mounts.ts';

/**
 Module logger for the container-side build step.
 */
const l = tagged({ tag: 'mutation-test-container', },);

/**
 Root rolldown bin inside the work tree; shims resolve through the
 symlinked pnpm store into the baked layer.
 */
const ROLLDOWN_BIN = join(
  WORK_MOUNT,
  'node_modules/.bin/rolldown',
);

/**
 Outcome of one package build.
 */
export type BuildOutcome = {
  readonly built: boolean;
  readonly clean: boolean;
  readonly durationMs: number;
  readonly detail: string;
};

/**
 Lists rolldown config files in one package directory.

 @param packageCwd - Package working directory.

 @returns Config file names, sorted.

 @example
 ```ts
 await listRolldownConfigs('/work/packages/module/fs-path');
 // ['rolldown.browser.config.ts']
 ```
 */
export async function listRolldownConfigs(packageCwd: string,): Promise<readonly string[]> {
  /**
   Directory entries of the package root.
   */
  const entries = await readdir(packageCwd,);
  return entries
    .filter(function isRolldownConfig(name,): boolean {
      return name.startsWith('rolldown.',) && name.endsWith('.config.ts',);
    },)
    .toSorted();
}

/**
 Builds one package by running every rolldown config sequentially.

 @param options - Package working directory.

 @returns Build outcome; `built` false means no configs exist.

 @example
 ```ts
 const outcome = await runBuildStep({ packageCwd });
 ```
 */
export async function runBuildStep(options: {
  readonly packageCwd: string;
},): Promise<BuildOutcome> {
  /**
   Logger scoped to this build invocation.
   */
  const rl = tagged({
    tag: runBuildStep.name,
    l,
  },);
  /**
   Start timestamp for duration measurement.
   */
  const startedAt = performance.now();
  /**
   rolldown config files declared by the package.
   */
  const configs = await listRolldownConfigs(options.packageCwd,);

  if (configs.length === 0)
    return {
      built: false,
      clean: true,
      durationMs: performance.now() - startedAt,
      detail: 'no rolldown configs; build step skipped',
    };

  /* oxlint-disable no-await-in-loop */
  // Configs of one package share output directories; sequential by design.
  for (const config of configs) {
    try {
      await spawn(
        ROLLDOWN_BIN,
        [
          '--configLoader',
          'native',
          '--config',
          config,
        ],
        { cwd: options.packageCwd, },
      );
    }
    catch (error) {
      rl.debug(`build rejected mutant via ${config}: ${String(error,)}`,);
      return {
        built: true,
        clean: false,
        durationMs: performance.now() - startedAt,
        detail: `${String(error,)} ${diagnosticsFromError(error,)}`.trim(),
      };
    }
  }
  /* oxlint-enable no-await-in-loop */

  return {
    built: true,
    clean: true,
    durationMs: performance.now() - startedAt,
    detail: '',
  };
}

/**
 Span splicing: applying one mutant to source text.

 @example
 ```ts
 spliceReplacement({ source: 'a + b', start: 2, end: 3, text: '-' });
 // 'a - b'
 ```
 */

/**
 Applies one replacement to source text by UTF-16 string slicing.

 yuku-parser's JS bindings return UTF-16 string offsets (probe-verified
 on multibyte and astral characters), so plain string slicing is exact;
 Buffer-based byte slicing at these offsets would corrupt output.

 @param options - Source text and replacement span.

 @returns Mutated source text.

 @throws Error when span is out of bounds or inverted.

 @example
 ```ts
 spliceReplacement({ source: 'true && x', start: 5, end: 7, text: '||' });
 // 'true || x'
 ```
 */
export function spliceReplacement(options: {
  readonly source: string;
  readonly start: number;
  readonly end: number;
  readonly text: string;
},): string {
  if ((options.start < 0)
    || (options.end
      > options.source
      .length)
    || (options.start > options.end))
    throw new Error(
      `replacement span ${String(options.start,)}..${String(options.end,)} out of bounds for source of length ${String(options.source
        .length,)}`,
    );

  return `${options.source
    .slice(
    0,
    options.start,
  )}${options.text}${options.source
    .slice(options.end,)}`;
}
